#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Reflection;
using System.Threading.Tasks;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using UnityEngine.TestTools;
namespace LastRail.Tests.EditMode {
 public class BLocalFlowContractTests {
  [Test] public void AValidatedFrozenLocalFlowBoundaryExists(){Assert.IsNotNull(typeof(BRefitSnapshot).Assembly.GetType("LastRail.Battle.BLocalFlowCandidate"));}
 }
 public class BLocalFlowTests {
  static JObject bundle;BSelectionController selection;BRefitController refit;BSelectionHttpTransport st;BRefitHttpTransport rt;BSelectionConnection sc;BRefitConnection rc;
  [OneTimeSetUp] public void Intake(){var raw=Environment.GetEnvironmentVariable("LASTRAIL_B_LOCAL_FLOW_PRIVATE");Environment.SetEnvironmentVariable("LASTRAIL_B_LOCAL_FLOW_PRIVATE",null);if(string.IsNullOrEmpty(raw))Assert.Ignore("Private actual LOCAL flow supervisor required");bundle=JObject.Parse(raw);}
  [OneTimeTearDown] public void Release()=>bundle=null;
  [TearDown] public void Close(){sc?.Dispose();rc?.Dispose();selection?.Dispose();refit?.Dispose();st?.Dispose();rt?.Dispose();}
  static IEnumerator Wait(Task task){while(!task.IsCompleted)yield return null;Assert.IsFalse(task.IsFaulted,"Safe actual exchange");Assert.IsFalse(task.IsCanceled);}
  static void Same(JToken a,JToken b)=>Assert.IsTrue(JToken.DeepEquals(a,b),"Frozen server source preserved");
  void Open(string name){st=new BSelectionHttpTransport(new BSelectionPrivateIntake((JObject)bundle[name]["selection"].DeepClone()));rt=new BRefitHttpTransport(new BRefitPrivateIntake((JObject)bundle[name]["refit"].DeepClone()));selection=new BSelectionController();refit=new BRefitController();sc=new BSelectionConnection(selection,st);rc=new BRefitConnection(refit,rt);}
  IEnumerator Saved(string name){Open(name);selection.Read();yield return Wait(sc.LastExchange);Assert.AreEqual(1,selection.State.Revision);var definition=selection.State.Selection.Capture();selection.Save(new BSelectionDefinition(definition),"flow-selection");yield return Wait(sc.LastExchange);selection.Read();yield return Wait(sc.LastExchange);Assert.AreEqual(1,selection.State.Revision);refit.Read();yield return Wait(rc.LastExchange);Assert.IsNull(refit.LastError);Assert.AreEqual(1,refit.State.SelectionRevision);refit.Save(new JArray(new JObject{["slot"]=0,["type"]="BCB01",["rank"]=1},new JObject{["slot"]=1,["type"]="BCB06",["rank"]=1}),"flow-refit");yield return Wait(rc.LastExchange);if(refit.Receipt==null){Assert.AreEqual(503,refit.LastError.Status);refit.ReplayOriginal();yield return Wait(rc.LastExchange);}refit.Read();yield return Wait(rc.LastExchange);}
  BLocalFlowCandidate Candidate()=>new BLocalFlowCandidate(st.AccountId,selection.State,refit.State,refit.OriginalRequest,refit.Receipt);
  static BDirectAttackInput Existing08Input(){var t=typeof(BDirectAttackBasicLoopTests);var flags=BindingFlags.NonPublic|BindingFlags.Static;var p=(JObject)t.GetMethod("Packet",flags).Invoke(null,new object[]{2});return (BDirectAttackInput)t.GetMethod("Input",flags).Invoke(null,new object[]{p});}
  [UnityTest] public IEnumerator ActualSelectionAndRefitFreezeExactPhysicalRanksAndRejectMissingOriginalActorProducer(){yield return Saved("workflow");var c=Candidate();Assert.IsFalse(c.StartReady);var frozen=c.Capture();Assert.AreEqual("a_physical1",(string)frozen["receipt"]["refit"]["cars"][0]["instanceId"]);Assert.AreEqual("op_eve",(string)frozen["receipt"]["refit"]["cars"][0]["occupant"]["operatorId"]);Assert.AreEqual(1,(int)frozen["receipt"]["refit"]["cars"][1]["rank"]);var ex=Assert.Throws<ArgumentException>(()=>c.Bind(Existing08Input(),new JObject(),"bad"));Assert.AreEqual("b_local_flow_attack_physical_source_missing",ex.Message);Same(frozen,c.Capture());File.WriteAllText((string)bundle["observationPath"],new JObject{["taskId"]="U-B-LOCAL-FLOW-10",["actualSelectionRevision"]=selection.State.Revision,["actualRefitRevision"]=refit.State.Revision,["candidateHash"]=c.OriginalHash,["candidate"]=frozen,["hpExecution"]="BLOCKED_UNSUPPLIED_MATCHING_ACTOR_PHYSICAL_INPUT",["neededOperator"]="op_eve",["neededInstances"]=new JArray("a_physical1","a_physical2"),["existingInputHash"]=Existing08Input().OriginalHash,["startReady"]=false}.ToString());}
  [UnityTest] public IEnumerator FollowingSelectionAndTypeChangeCannotRewriteAlreadyCapturedCandidate(){yield return Saved("freeze");var c=Candidate();var before=c.Capture();var hash=c.OriginalHash;refit.Save(new JArray(new JObject{["slot"]=0,["type"]="BCB04",["rank"]=1},new JObject{["slot"]=1,["type"]="BCB06",["rank"]=1}),"different-type");yield return Wait(rc.LastExchange);refit.Read();yield return Wait(rc.LastExchange);var changed=Candidate();Assert.AreNotEqual(c.OriginalHash,changed.OriginalHash);Assert.AreEqual("BCB04",(string)changed.Capture()["receipt"]["refit"]["cars"][0]["type"]);Same(before,c.Capture());var d=selection.State.Selection.Capture();var rows=(JArray)d["placements"];var old=rows[0]["occupant"].DeepClone();rows[0]["occupant"]=rows[1]["occupant"].DeepClone();rows[1]["occupant"]=old;selection.Save(new BSelectionDefinition(d),"next-selection");yield return Wait(sc.LastExchange);selection.Read();yield return Wait(sc.LastExchange);refit.Read();yield return Wait(rc.LastExchange);Assert.AreEqual(409,refit.LastError.Status);Assert.AreEqual("combat_b_refit_selection_conflict",refit.LastError.Code);Assert.Throws<ArgumentException>(()=>Candidate());Same(before,c.Capture());Assert.AreEqual(hash,c.OriginalHash);}
  [UnityTest] public IEnumerator CrossAccountRevisionOccupantInstanceHashAndOldReceiptCannotPublishANewCandidate(){yield return Saved("mismatch");var current=Candidate().Capture();Assert.Throws<ArgumentException>(()=>new BLocalFlowCandidate("b",selection.State,refit.State,refit.OriginalRequest,refit.Receipt));foreach(var field in new[]{"revision","occupant","owned","catalog"}){var s=selection.State.Capture();if(field=="revision")s["revision"]=3;if(field=="occupant"){var rows=(JArray)s["selection"]["placements"];var o=rows[0]["occupant"].DeepClone();rows[0]["occupant"]=rows[1]["occupant"].DeepClone();rows[1]["occupant"]=o;}if(field=="owned")s["ownedSource"]["operators"]=new JArray();if(field=="catalog")s["savedCatalog"]["revision"]=2;Assert.Throws<ArgumentException>(()=>new BLocalFlowCandidate("a",new BSelectionSnapshot(s),refit.State,refit.OriginalRequest,refit.Receipt));}foreach(var field in new[]{"instance","sourceHash","definitionHash","account","receiptRevision"}){var a=refit.Receipt;if(field=="instance")a["refit"]["cars"][0]["instanceId"]="foreign-physical";if(field=="sourceHash")a["sourceHash"]=new string('a',64);if(field=="definitionHash")a["definitionHash"]=new string('b',64);if(field=="account")a["refit"]["accountId"]="b";if(field=="receiptRevision")a["revision"]=2;Assert.Throws<ArgumentException>(()=>new BLocalFlowCandidate("a",selection.State,refit.State,refit.OriginalRequest,a));}Same(current,Candidate().Capture());Assert.AreEqual(0,st.InFlightCount+rt.InFlightCount);}
  [UnityTest] public IEnumerator LostAcknowledgementRequiresOriginalReplayBeforeFreezingActualSavedState(){yield return Saved("lost");var original=refit.OriginalRequest;var ack=refit.Receipt;var c=Candidate();refit.ReplayOriginal();yield return Wait(rc.LastExchange);Same(ack,refit.Receipt);Assert.AreSame(original,refit.OriginalRequest);Same(c.Capture(),Candidate().Capture());Assert.IsFalse(c.StartReady);Assert.AreEqual(0,rt.InFlightCount);}
 }
}
#endif